using System.Net;
using System.Text.Json;
using EduConnect.Mvc.Models;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Xunit;
internal static partial class Cases
{
 internal static async Task HttpCases(Fixture f,string key)
 {
  switch(key){
  case "auth_login_http":{
   using var c=await f.Client();await using var db=f.Db();var email=(await db.Users.SingleAsync(x=>x.Id==f.H)).Email!;using var r=await f.Post(c,"/TaiKhoan/DangNhap",new(){{"Email",email},{"MatKhau",Fixture.Password},{"ReturnUrl","/NhuCau/NhuCau/Index"}},ajax:false);Assert.Equal(HttpStatusCode.Redirect,r.StatusCode);Assert.Equal("/NhuCau/NhuCau/Index",r.Headers.Location!.OriginalString);var cookies=r.Headers.GetValues("Set-Cookie").ToList();Assert.Contains(cookies,x=>x.StartsWith("EduConnect.Identity=")&&x.Contains("httponly",StringComparison.OrdinalIgnoreCase)&&x.Contains("secure",StringComparison.OrdinalIgnoreCase));using var page=await c.GetAsync(r.Headers.Location);Assert.Equal(HttpStatusCode.OK,page.StatusCode);Assert.Single(await db.Set<PhienDangNhap>().Where(x=>x.TaiKhoanId==f.H&&x.ThuHoiLuc==null).ToListAsync());break;}
  case "auth_register_http":{
   foreach(var role in new[]{"HocSinh","PhuHuynh","GiaSu"}){using var c=await f.Client();var email=f.Tag+role+"@example.invalid";using var r=await f.Post(c,"/TaiKhoan/DangKy",Register(email,role),"/TaiKhoan/DangKy",ajax:false);Assert.Equal(HttpStatusCode.Redirect,r.StatusCode);Assert.Contains("DangNhap",r.Headers.Location!.OriginalString);await using var db=f.Db();var u=await db.Users.SingleAsync(x=>x.NormalizedEmail==email.ToUpperInvariant());Assert.NotEqual(Fixture.Password,u.PasswordHash);var roles=await db.UserRoles.Where(x=>x.UserId==u.Id).Join(db.Roles,r=>r.RoleId,r=>r.Id,(ur,r)=>r.Name).ToListAsync();Assert.Equal(new[]{role},roles);Assert.Equal(role=="HocSinh",await db.Set<HocSinh>().AnyAsync(x=>x.TaiKhoanId==u.Id));Assert.Equal(role=="GiaSu",await db.Set<GiaSu>().AnyAsync(x=>x.TaiKhoanId==u.Id));Assert.Equal(role=="PhuHuynh",await db.Set<PhuHuynh>().AnyAsync(x=>x.TaiKhoanId==u.Id));Assert.False(await db.Set<PhienDangNhap>().AnyAsync(x=>x.TaiKhoanId==u.Id));}break;}
  case "auth_register_reject":{
   await using var db=f.Db();var email=(await db.Users.SingleAsync(x=>x.Id==f.H)).Email!;for(int dl=0;dl<3;dl++){using var c=await f.Client();var form=Register(dl==0?" "+email.ToUpperInvariant()+" ":f.Tag+dl+"@example.invalid",dl==1?"QuanTri":"HocSinh");if(dl==2){form["MatKhau"]="short";form["XacNhanMatKhau"]="short";}using var r=await f.Post(c,"/TaiKhoan/DangKy",form,"/TaiKhoan/DangKy",ajax:false);Assert.Equal(HttpStatusCode.OK,r.StatusCode);Assert.False(r.Headers.TryGetValues("Set-Cookie",out var cookies)&&cookies.Any(x=>x.StartsWith("EduConnect.Identity=")));var body=await r.Content.ReadAsStringAsync();Assert.DoesNotContain("PasswordHash",body);Assert.DoesNotContain("SqlException",body);}Assert.Equal(5,await db.Users.CountAsync(x=>x.HoTen==f.Tag));break;}
  case "auth_lock_counter":{
   await using var db=f.Db();var user=await db.Users.SingleAsync(x=>x.Id==f.H);for(int dl=0;dl<4;dl++){await f.Sql("UPDATE dbo.AspNetUsers SET TrangThai=@state WHERE Id=@u",new(){{"@state",dl==1?"BiKhoa":"HoatDong"},{"@u",f.H}});if(dl==2)await f.Sql("DELETE dbo.TrangThaiThuDangNhap WHERE LoaiKhoa='TaiKhoan' AND GiaTriKhoa=@a; INSERT dbo.TrangThaiThuDangNhap(LoaiKhoa,GiaTriKhoa,SoLanSai,LanSaiCuoiLuc,ChoDenLuc) VALUES('TaiKhoan',@a,5,SYSDATETIMEOFFSET(),DATEADD(minute,5,SYSDATETIMEOFFSET()))",new(){{"@a",user.NormalizedEmail}});using var c=await f.Client();using var r=await f.Post(c,"/TaiKhoan/DangNhap",new(){{"Email",dl==3?f.Tag+"unknown@example.invalid":user.Email!},{"MatKhau",dl is 1 or 2?Fixture.Password:"Wrong password attempt!"}},ajax:false);Assert.Equal(HttpStatusCode.OK,r.StatusCode);Assert.False(r.Headers.TryGetValues("Set-Cookie",out var cookies)&&cookies.Any(x=>x.StartsWith("EduConnect.Identity=")));}Assert.False(await db.Set<PhienDangNhap>().AnyAsync(x=>x.TaiKhoanId==f.H));break;}
  case "auth_return_url":{
   await using var db=f.Db();var email=(await db.Users.SingleAsync(x=>x.Id==f.H)).Email!;foreach(var url in new[]{"https://external.example","//external.example","/NhuCau/NhuCau/Index"}){using var c=await f.Client();using var r=await f.Post(c,"/TaiKhoan/DangNhap",new(){{"Email",email},{"MatKhau",Fixture.Password},{"ReturnUrl",url}},ajax:false);Assert.Equal(HttpStatusCode.Redirect,r.StatusCode);var location=r.Headers.Location!.OriginalString;Assert.StartsWith("/",location);Assert.DoesNotContain("external.example",location);if(url.StartsWith("/NhuCau"))Assert.Equal(url,location);}break;}
  case "auth_logout":{
   using var c=await f.Client(f.H);using var r=await f.Post(c,"/TaiKhoan/DangXuat",[],ajax:false);Assert.Equal(HttpStatusCode.Redirect,r.StatusCode);await using var db=f.Db();Assert.False(await db.Set<PhienDangNhap>().AnyAsync(x=>x.TaiKhoanId==f.H&&x.ThuHoiLuc==null));c.DefaultRequestHeaders.TryAddWithoutValidation("X-Requested-With","XMLHttpRequest");using var deny=await c.GetAsync("/NhuCau/NhuCau/Index");Assert.Equal(HttpStatusCode.Unauthorized,deny.StatusCode);break;}
  case "auth_change_password":{
   using var one=await f.Client(f.H);using var two=await f.Client(f.H);const string next="Changed integration password 2026!";using var r=await f.Post(one,"/TaiKhoan/DoiMatKhau",new(){{"MatKhauHienTai",Fixture.Password},{"MatKhau",next},{"XacNhanMatKhau",next}},"/TaiKhoan/DoiMatKhau",ajax:false);Assert.Equal(HttpStatusCode.Redirect,r.StatusCode);two.DefaultRequestHeaders.TryAddWithoutValidation("X-Requested-With","XMLHttpRequest");using var denied=await two.GetAsync("/NhuCau/NhuCau/Index");Assert.Equal(HttpStatusCode.Unauthorized,denied.StatusCode);await using var db=f.Db();var u=await db.Users.SingleAsync(x=>x.Id==f.H);var hasher=new PasswordHasher<TaiKhoan>();Assert.Equal(PasswordVerificationResult.Failed,hasher.VerifyHashedPassword(u,u.PasswordHash!,Fixture.Password));Assert.NotEqual(PasswordVerificationResult.Failed,hasher.VerifyHashedPassword(u,u.PasswordHash!,next));Assert.False(await db.Set<PhienDangNhap>().AnyAsync(x=>x.TaiKhoanId==f.H&&x.ThuHoiLuc==null));break;}
  case "auth_session_expired":{
   for(int dl=0;dl<3;dl++){using var c=await f.Client(f.H);if(dl==0)await f.Sql("UPDATE dbo.PhienDangNhap SET TaoLuc=DATEADD(hour,-2,SYSDATETIMEOFFSET()),HoatDongCuoiLuc=DATEADD(minute,-31,SYSDATETIMEOFFSET()) WHERE TaiKhoanId=@u",new(){{"@u",f.H}});if(dl==1)await f.Sql("UPDATE dbo.PhienDangNhap SET ThuHoiLuc=SYSDATETIMEOFFSET() WHERE TaiKhoanId=@u",new(){{"@u",f.H}});if(dl==2)await f.Sql("UPDATE dbo.AspNetUsers SET TrangThai='BiKhoa' WHERE Id=@u",new(){{"@u",f.H}});c.DefaultRequestHeaders.TryAddWithoutValidation("X-Requested-With","XMLHttpRequest");using var denied=await c.GetAsync("/NhuCau/NhuCau/Index");await f.Record(denied);Assert.Equal(HttpStatusCode.Unauthorized,denied.StatusCode);}break;}
  case "search_guest":{
   await f.SeedNeed();using var c=await f.Client();foreach(var url in new[]{"/TimKiem/TimKiem/Index?MonHocId="+f.M1,"/TimKiem/TimKiem/ChiTiet/"+f.Need,"/NhuCau/HoSoGiaSu/ChiTiet?maHoSo="+f.Profile}){using var r=await c.GetAsync(url);await f.Record(r);Assert.Equal(HttpStatusCode.OK,r.StatusCode);Assert.Contains(f.Tag,await r.Content.ReadAsStringAsync());}using var deny=await f.Post(c,"/KetNoi/KetNoi/GuiLienHe",new(){{"DoiTuongId",f.G.ToString()},{"LoiNhan","Liên hệ"}});Assert.Equal(HttpStatusCode.Unauthorized,deny.StatusCode);break;}
  case "search_binding":{
   using var c=await f.Client();c.DefaultRequestHeaders.TryAddWithoutValidation("X-Requested-With","XMLHttpRequest");using var r=await c.GetAsync("/TimKiem/TimKiem/Index?Trang=abc");await f.Record(r);Assert.Equal(HttpStatusCode.BadRequest,r.StatusCode);break;}
  case "search_compare":{
   using var c=await f.Client();var profiles=new List<Guid>{f.Profile};for(int i=0;i<2;i++){var g=await f.User("GiaSu");await using var db=f.Db();var h=new HoSoGiaSu{Id=Guid.NewGuid(),GiaSuId=g,TrinhDo="Đại học",ChuyenMon=f.Tag,KinhNghiem="3 năm",MoTa=f.Tag,TrangThaiDuyet="DaDuyet",DangHienThi=true,DayTrucTuyen=true};db.Add(h);await db.SaveChangesAsync();db.Add(new HoSoGiaSuMonDay{HoSoGiaSuId=h.Id,MonHocId=f.M1,PhamViDay="Lớp 8",HocPhiDeXuat=150000,DonViHocPhi="VND/Gio"});await db.SaveChangesAsync();profiles.Add(h.Id);}foreach(var ids in new[]{profiles.Take(2).ToArray(),profiles.ToArray(),new[]{profiles[0],profiles[0],profiles[1]}}){using var r=await c.GetAsync("/TimKiem/TimKiem/SoSanh?"+string.Join('&',ids.Select(id=>"ids="+id)));await f.Record(r);Assert.Equal(HttpStatusCode.OK,r.StatusCode);var body=await r.Content.ReadAsStringAsync();foreach(var id in ids.Distinct())Assert.Contains(id.ToString(),body,StringComparison.OrdinalIgnoreCase);var head=System.Text.RegularExpressions.Regex.Match(body,"<thead>\\s*<tr>(.*?)</tr>",System.Text.RegularExpressions.RegexOptions.Singleline);Assert.True(head.Success,"Comparison header table missing");Assert.Equal(ids.Distinct().Count()+1,System.Text.RegularExpressions.Regex.Matches(head.Groups[1].Value,"<th\\b").Count); }break;}
  case "search_compare_reject":{
   await f.SeedNeed();Guid hidden;var gh=await f.User("GiaSu");await using(var db=f.Db()){hidden=Guid.NewGuid();db.Add(new HoSoGiaSu{Id=hidden,GiaSuId=gh,TrinhDo="Đại học",ChuyenMon=f.Tag,KinhNghiem="3 năm",MoTa=f.Tag,TrangThaiDuyet="ChoDuyet",DangHienThi=false});await db.SaveChangesAsync();}using var c=await f.Client();c.DefaultRequestHeaders.TryAddWithoutValidation("X-Requested-With","XMLHttpRequest");var inputs=new[]{new[]{f.Profile},new[]{f.Profile,Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid()},new[]{f.Profile,f.Need},new[]{f.Profile,hidden}};for(int i=0;i<inputs.Length;i++){using var r=await c.GetAsync("/TimKiem/TimKiem/SoSanh?"+string.Join('&',inputs[i].Select(id=>"ids="+id)));await f.Record(r);Assert.Equal(i==3?HttpStatusCode.NotFound:HttpStatusCode.BadRequest,r.StatusCode);if(i==3)Assert.DoesNotContain(f.Tag,await r.Content.ReadAsStringAsync());}break;}
  case "contact_http":{
   using var c=await f.Client(f.H);using var r=await f.Post(c,"/KetNoi/KetNoi/GuiLienHe",new(){{"DoiTuongId",f.G.ToString()},{"LoiNhan","Trao đổi lịch học"},{"maNguoiThucHien",f.X.ToString()}});Assert.Equal(HttpStatusCode.OK,r.StatusCode);await using var db=f.Db();var row=await db.Set<YeuCauLienHe>().SingleAsync(x=>x.GiaSuId==f.G&&x.BenHocId==f.H);Assert.Equal(f.H,row.NguoiGuiId);Assert.Equal("Trao đổi lịch học",row.LoiNhan);Assert.False(await db.Set<YeuCauLienHe>().AnyAsync(x=>x.NguoiGuiId==f.X));break;}
  case "contact_reject":{
   for(int dl=0;dl<4;dl++){await using var d=new Fixture(f.Id+"-DL"+dl);await d.Init();if(dl==1)await d.Sql("UPDATE dbo.AspNetUsers SET TrangThai='BiKhoa' WHERE Id=@g",new(){{"@g",d.G}});if(dl==2)await d.Sql("UPDATE dbo.HoSoGiaSu SET DangHienThi=0 WHERE Id=@p",new(){{"@p",d.Profile}});using var c=await d.Client(d.H);using var r=await d.Post(c,"/KetNoi/KetNoi/GuiLienHe",new(){{"DoiTuongId",(dl==0?d.H:d.G).ToString()},{"LoiNhan",dl==3?"":"Liên hệ"}});Assert.Equal(new[]{400,400,409,422}[dl],(int)r.StatusCode);await using var db=d.Db();Assert.False(await db.Set<YeuCauLienHe>().AnyAsync(x=>x.BenHocId==d.H));}break;}
  case "contact_reply":{
   for(int dl=0;dl<4;dl++){await using var d=new Fixture(f.Id+"-DL"+dl);await d.Init();await d.SeedContact(false);var rv=await d.Version<YeuCauLienHe>(d.Contact);if(dl==3)await d.Sql("UPDATE dbo.YeuCauLienHe SET LoiNhan=N'Đã đổi' WHERE Id=@c",new(){{"@c",d.Contact}});using var c=await d.Client(dl==2?d.X:d.G);using var r=await d.Post(c,"/KetNoi/KetNoi/PhanHoiLienHe",new(){{"id",d.Contact.ToString()},{"action",dl==1?"TuChoi":"ChapNhan"},{"rowVersion",Convert.ToBase64String(rv)}});Assert.Equal(new[]{200,200,403,409}[dl],(int)r.StatusCode);await using var db=d.Db();var saved=await db.Set<YeuCauLienHe>().SingleAsync(x=>x.Id==d.Contact);Assert.Equal(dl==0?"ChapNhan":dl==1?"TuChoi":"ChoPhanHoi",saved.TrangThai);Assert.Equal(dl==0?1:0,await db.Set<CuocHoiThoai>().CountAsync(x=>x.LienHeId==d.Contact));}break;}
  case "class_http":case "class_receiver":{
   await f.SeedProposal();var actors=key=="class_http"?new[]{f.H}:new[]{f.G,f.X};foreach(var actor in actors){using var c=await f.Client(actor);using var r=await f.Post(c,"/KetNoi/KetNoi/ChapNhan",new(){{"MaYeuCau",f.Request.ToString()},{"RowVersion",Convert.ToBase64String(await f.Version<YeuCauKetNoiLopHoc>(f.Request))}});Assert.Equal(key=="class_http"?HttpStatusCode.OK:HttpStatusCode.Forbidden,r.StatusCode);if(key=="class_http"){await using var db=f.Db();var row=await db.Set<LopHoc>().SingleAsync(x=>x.YeuCauKetNoiId==f.Request);Assert.Contains("/HocTap/LopHoc/ChiTiet/"+row.Id,await r.Content.ReadAsStringAsync());f.Class=row.Id;await ClassGraph(f);}}if(key=="class_receiver"){await using var db=f.Db();Assert.False(await db.Set<LopHoc>().AnyAsync(x=>x.YeuCauKetNoiId==f.Request));}break;}
  case "progress_auth":{
   await f.SeedClass();using var c=await f.Client(f.X);c.DefaultRequestHeaders.TryAddWithoutValidation("X-Requested-With","XMLHttpRequest");using var r=await c.GetAsync("/HocTap/LopHoc/ChiTiet/"+f.Class+"?tab=progress");await f.Record(r);Assert.Equal(HttpStatusCode.Forbidden,r.StatusCode);break;}
  default:throw new InvalidOperationException(key);
  }
 }
 static Dictionary<string,string> Register(string email,string role)=>new(){{"HoTen","Kiểm thử tích hợp"},{"Email",email},{"VaiTro",role},{"MatKhau",Fixture.Password},{"XacNhanMatKhau",Fixture.Password}};
}
